<script setup>
import { ref } from 'vue'
const props = defineProps({ request: Function, user: Object })
const question = ref(''); const answer = ref(''); const sources = ref([]); const loading = ref(false)
const prompts = ['最近有什么计算机竞赛？','大四有哪些就业活动？','最近有哪些奖学金通知？','有什么适合我的讲座？']
async function ask(text = question.value) { if (!text.trim()) return; question.value = text; loading.value = true; try { const data = await props.request('/rag/ask', { method: 'POST', headers: {'Content-Type':'application/json'}, body: JSON.stringify({ question: text }) }); answer.value = data.answer; sources.value = data.sources || [] } finally { loading.value = false } }
</script>
<template><section class="chat-view"><div class="chat-layout"><aside class="chat-history"><p class="eyebrow blue">CAMPUS AI</p><h3>对话记录</h3><div class="history-item active">校园信息问答</div><div class="history-item">我的活动推荐</div><div class="history-item">就业与升学</div></aside><div class="chat-main"><div class="chat-topline"><div><p class="eyebrow blue">GROUNDED ANSWERS</p><h1>有什么校园问题想了解？</h1><p>基于校园信息库回答，重要信息都有来源。</p></div><span class="ai-status"><i></i>资料库已连接</span></div><div v-if="!answer" class="prompt-grid"><button v-for="prompt in prompts" :key="prompt" @click="ask(prompt)">{{ prompt }} <span>→</span></button></div><div v-else class="chat-answer"><div class="answer-avatar">C</div><div><p>{{ loading ? '正在检索校园资料…' : answer }}</p><div v-if="sources.length" class="source-list"><span>来源</span><div v-for="source in sources" :key="source.content_id" class="source-card"><strong>{{ source.title }}</strong><small>校园信息库</small></div></div></div></div><form class="chat-input" @submit.prevent="ask()"><input v-model="question" placeholder="搜索活动、竞赛、通知、就业信息…"><button :disabled="loading || !question.trim()">↑</button></form></div></div></section></template>
